import {sources,lessons,assignments,metricDefinitions} from './course.mjs';
import {aggregate,groupRows,filteredRows,divide} from './analytics.mjs';
import {esc,num,usd,pct,bars,scatter,metricCards,metricsTable} from './charts.mjs';
import {overview} from './app.mjs';
import {investigationViews} from './investigation-views.mjs';
import {allocateBudget} from './investigation.mjs';
export function views(state,localAvailable){
const extra=investigationViews(state);
const head=(label,title,desc,extra='')=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;
const source=()=>state.data?`<div class="source-note"><span class="pill">${state.data.meta.sourceKind==='public-course-mirror'?'公开课程镜像':'本地导入文件'}</span><span>${esc(state.data.meta.filename)} · ${num(state.data.rows.length)} 条记录</span><a href="#data">查看来源与检查 →</a></div>`:'';
const empty=()=>`<div class="empty"><div class="badge-icon">▥</div><strong>先导入案例表格，再开始计算</strong><p>图表、指标与数值校验从 KEL321 文件计算，不预填示例经营数据。</p><a class="button primary" href="#data">准备案例数据 →</a></div>`;
const note=extra.note;
const pager=(page,count,size,action)=>`<div class="pagination"><span>${num(count)} 条 · 第 ${page+1} / ${Math.max(1,Math.ceil(count/size))} 页</span><div><button class="button compact" data-action="${action}" data-delta="-1" ${page===0?'disabled':''}>上一页</button> <button class="button compact" data-action="${action}" data-delta="1" ${(page+1)*size>=count?'disabled':''}>下一页</button></div></div>`;
const pairs=rows=>`<div class="result-list">${rows.map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>`;
function task(id){const a=assignments[id];return `${extra.initial(id)}${id==='q4'?extra.chain():''}<div class="grid-main"><div><section class="panel question-panel"><div class="eyebrow">业务任务</div><h2>${a.question}</h2><p>${a.context}</p><ol class="task-list">${a.tasks.map((t,i)=>`<li><span class="task-index">${i+1}</span><div><h3>${t[0]}</h3><p>${t[1]}</p></div></li>`).join('')}</ol><details class="hint"><summary>卡住时，查看一个提示</summary><p>${a.hint}</p></details></section>${note(id)}</div><aside class="side-stack"><section class="panel aside-card"><h3>本题交付物</h3><p>${a.deliverable}</p><button class="button primary" data-action="tab" data-tab="analysis">打开分析工作台 →</button></section><section class="panel aside-card"><h3>评阅依据 · 25 分</h3><ul class="rubric">${a.rubric.map(x=>`<li>${x}</li>`).join('')}</ul><p class="small">经营判断由讲师评阅，不自动判成唯一答案。</p><h3 style="margin-top:22px">涉及的数据</h3><div class="tags">${a.fields.map(f=>`<span class="tag">${f}</span>`).join('')}</div></section></aside></div>`}
function q1(){const t=aggregate(state.data.rows),a=state.data.audit;return extra.audit()+metricCards(t)+`<section class="panel"><h2>投放路径与计数</h2><div class="funnel">${[['曝光',num(t.impressions),'Impressions'],['点击',num(t.clicks),'CTR '+pct(t.ctr)],['预订',num(t.bookings),'预订 / 点击 '+pct(t.cvr)],['销售收入',usd(t.revenue),'每次预订 '+usd(t.revenuePerBooking,2)]].map(([l,v,n])=>`<div><span>${l}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><p class="chart-caption">框宽不表示比例。不同事件计数不等于独立用户漏斗。</p></section><div class="two-columns"><section class="panel"><h2>检查指标的分母</h2>${pairs([['加权 CPC',usd(t.cpc,2)],['每次预订成本 CPA',usd(t.cpa,2)],['预订 / 点击 CVR',pct(t.cvr)],['销售收入 − 广告花费',usd(t.balance,2)]])}<div class="notice info"><p>广告费后余额尚未扣除履约等成本，不称为利润。</p></div></section><section class="panel"><h2>先检查，再判断</h2>${pairs([['预订量高于点击',a.bookingsAboveClicks+' 条'],['零预订',num(a.zeroBookings)+' 条'],['零点击',a.zeroClicks+' 条']])}<p class="small">异常记录保留在汇总中，应回到源头核对口径。</p><label for="cpa-check" class="field-label">自行计算整体 CPA（USD）</label><div class="flex"><input id="cpa-check" type="number" min="0" step="0.01" placeholder="输入你的计算值"><button class="button" data-action="check-cpa">核对</button></div><p id="cpa-feedback" role="status" class="small"></p></section></div>${note('q1')}`}
function q2(){const groups=groupRows(state.data.rows,'publisher'),t=aggregate(state.data.rows);return `<section class="panel"><div class="section-head no-margin"><h2>渠道的成本与转化表现</h2><button class="button compact" data-action="export-summary">导出渠道汇总 ↓</button></div>${scatter(groups,t)}</section><section class="panel"><h2>把规模与效率一起看</h2>${metricsTable(groups)}<p class="chart-caption">DoubleClick 全量汇总 · 保留渠道原始名称 · Kayak 独立分析</p></section><div class="two-columns"><section class="panel"><h2>预算花在哪里</h2>${bars(groups,{title:'广告花费'})}</section><section class="panel"><h2>读图后，再决定动作</h2><ul class="reading-list"><li>低 CPC、高 CVR：验证是否还有有效流量可获取。</li><li>高 CPC、高 CVR：结合 CPA 和每次预订收入判断成本。</li><li>低 CPC、低 CVR：检查关键词意图、广告与落地页的匹配。</li><li>高 CPC、低 CVR：继续下钻，考虑收缩或调整。</li></ul><p class="small">这些是诊断线索，优化的实际效果仍需验证。</p></section></div>${extra.mix()}${note('q2')}`}
function q3(){const data=state.data.rows,pubs=groupRows(data,'publisher'),scope=filteredRows(data,{publisher:state.publisher});const campaigns=groupRows(scope.map(r=>({...r,scopeCampaign:state.publisher?r.campaign:r.publisher+' / '+r.campaign})),'scopeCampaign');const detail=filteredRows(data,{publisher:state.publisher,query:state.query,minClicks:state.minClicks}).sort((a,b)=>b.cost-a.cost),size=12;state.page=Math.min(state.page,Math.max(0,Math.ceil(detail.length/size)-1));return `<section class="panel"><div class="filters"><label>渠道<select id="publisher-filter"><option value="">全部渠道（保留渠道 + 活动）</option>${pubs.map(p=>`<option ${state.publisher===p.name?'selected':''} value="${esc(p.name)}">${esc(p.name)}</option>`).join('')}</select></label><label>关键词包含<input type="search" id="keyword-query" value="${esc(state.query)}" placeholder="例如 air france"></label><label>关键词最少点击<input type="number" id="min-clicks" min="0" step="1" value="${state.minClicks}"></label><button class="button" data-action="apply-filters">应用筛选</button></div><p class="small no-margin">关键词筛选影响关键词表和门槛分析；点击门槛是敏感性参照。活动比较保留当前渠道全量。</p></section>${extra.diagnostic()}<div class="two-columns"><section class="panel"><h2>哪些活动占用了主要预算</h2>${bars(campaigns,{title:'活动花费',limit:8})}</section><section class="panel"><h2>先圈定行动候选</h2>${pairs([['当前渠道',state.publisher?esc(state.publisher):'全部渠道'],['活动组合',num(campaigns.length)],['符合关键词筛选',num(detail.length)+' 条'],['其中零预订的花费',usd(aggregate(detail.filter(r=>r.bookings===0)).cost,2)]])}<p class="small">零预订只表示当前观察窗口没有记录到预订，不能直接证明未来没有价值。</p></section></div><section class="panel"><h2>活动经营对比</h2>${metricsTable(campaigns.slice(0,10),{caption:'按花费排序的前 10 个渠道 / 活动组合',showPublisher:true})}</section><section class="panel"><div class="section-head no-margin"><h2>关键词行动清单</h2><button class="button compact" data-action="export-keywords">导出筛选结果 ↓</button></div><div class="table-scroll"><table><caption>关键词明细，按花费降序</caption><thead><tr><th>源行</th><th>渠道 / 活动 / 关键词</th><th>匹配 / 出价策略</th><th>点击</th><th>花费</th><th>预订</th><th>ROAS</th></tr></thead><tbody>${detail.slice(state.page*size,(state.page+1)*size).map(r=>`<tr><td>${r.sourceRow}</td><th>${esc(r.keyword)}<small>${esc(r.publisher)} / ${esc(r.campaign)}</small></th><td>${esc(r.matchType)}<small>${esc(r.bidStrategy)}</small></td><td>${num(r.clicks)}</td><td>${usd(r.cost,2)}</td><td>${num(r.bookings)}</td><td>${num(divide(r.revenue,r.cost),2)}×</td></tr>`).join('')||'<tr><td colspan="7">没有符合条件的关键词，请调整筛选。</td></tr>'}</tbody></table></div>${pager(state.page,detail.length,size,'keywords-page')}</section>${note('q3')}`}
function q4(){const groups=groupRows(state.data.rows,'publisher');if(!Object.keys(state.budgets).length){state.cap=Number(aggregate(state.data.rows).cost.toFixed(2));state.budgets=allocateBudget(groups,state.cap)||{};state.cpcChange=0;state.cvrChange=0;state.expansionDrop=0}return `<div class="notice info"><p><strong>固定效率情景，不是预测。</strong>初始配置沿用历史花费。扩量后的效率是否成立，需要另行验证；未构造额外需求曲线。</p></div><div class="scenario-grid"><section class="panel"><h2>1. 分配预算</h2><label class="field-label" for="budget-cap">共同预算总额（USD，同等统计期间）</label><input id="budget-cap" type="number" min="0" step="0.01" value="${Number.isFinite(state.cap)?state.cap.toFixed(2):''}"><div class="budget-rows">${groups.map(g=>`<label><span>${esc(g.name)}<small>历史 ${usd(g.cost,2)}</small></span><input type="number" min="0" step="0.01" data-budget="${esc(g.name)}" value="${Number.isFinite(state.budgets[g.name])?state.budgets[g.name].toFixed(2):''}" aria-label="${esc(g.name)} 预算"></label>`).join('')}</div><button class="button quiet" data-action="reset-budget">恢复历史花费分配</button><button class="button quiet" data-action="seed-roas">载入 ROAS 权重基准</button></section><div><section class="panel"><h2>2. 公开你的假设</h2><label class="slider-label" for="cpc-change">点击成本相对变化 <strong id="cpc-change-label">${state.cpcChange}%</strong></label><input type="range" id="cpc-change" min="-50" max="100" step="5" value="${state.cpcChange}"><div class="range-ends"><span>-50%</span><span>历史水平 0%</span><span>+100%</span></div><label class="slider-label" for="cvr-change">预订率相对变化 <strong id="cvr-change-label">${state.cvrChange}%</strong></label><input type="range" id="cvr-change" min="-80" max="100" step="5" value="${state.cvrChange}"><div class="range-ends"><span>-80%</span><span>历史水平 0%</span><span>+100%</span></div><p class="small">每次预订收入沿用该渠道历史值。相对变化不是百分点变化；CVR 增加 10% 表示乘以 1.1。</p></section><section class="panel"><h2>新增分配部分的压力假设</h2><label class="slider-label" for="expansion-drop">额外 CVR 折损 <strong id="expansion-drop-label">${state.expansionDrop}%</strong></label><input type="range" id="expansion-drop" min="0" max="80" step="5" value="${state.expansionDrop}"><p class="small">只作用于超过“同预算历史占比分配”的预算部分。用于挑战扩量假设，不表示真实流量容量或预测。共同 CPC/CVR 变化仍作用于全部预算。</p></section></div></div><section class="panel"><h2>3. 同预算三方案对照</h2><div id="scenario-results" aria-live="polite"></div></section>${extra.chain()}<section class="panel"><h2>模型边界与下一步验证</h2><p>没有考虑流量上限、边际成本、关键词结构改变、季节性或机票履约成本。情景销售收入与历史销售收入的差额，不能称为广告因果增量。</p><div class="formula">预算 ÷ 假设 CPC × 假设 CVR × 历史每次预订收入</div></section>${note('q4')}`}
function reference(id){if(!state.data)return empty();const d=state.data,t=aggregate(d.rows),groups=groupRows(d.rows,'publisher'),best=[...groups].sort((a,b)=>(b.roas??-1)-(a.roas??-1))[0];const simple=divide(d.rows.filter(r=>r.clicks>0).reduce((s,r)=>s+r.cost/r.clicks,0),d.rows.filter(r=>r.clicks>0).length);const copy={q1:`<p>主表花费 <strong>${usd(t.cost,2)}</strong>、预订 <strong>${num(t.bookings)}</strong>、销售收入 <strong>${usd(t.revenue,2)}</strong>。加权 CPC 为 ${usd(t.cpc,2)}，CPA 为 ${usd(t.cpa,2)}，ROAS 为 ${num(t.roas,2)} 倍。</p><p>有点击记录的逐行 CPC 简单平均为 ${usd(simple,4)}，整体加权 CPC 为 ${usd(t.cpc,4)}。前者每行权重相同，后者按点击量加权。</p><p>${d.audit.bookingsAboveClicks} 条预订高于点击的记录应核对口径，不能直接删掉。预订 / 点击不等于用户购买概率。</p>`,q2:`<p><strong>${esc(groups[0].name)}</strong> 花费最高，占整体 ${pct(groups[0].cost/t.cost)}；<strong>${esc(best.name)}</strong> 历史 ROAS 最高，为 ${num(best.roas,2)} 倍。</p><p>两种排序回答不同问题。扩量还应结合样本量、当前规模、关键词结构和新增流量可得性。不能只按最高 ROAS 推出唯一的最优预算。</p><p>四象限参考线用整体加权值；保留 US、Global、Overture 的源标签，避免未经核实就合并渠道。</p>`,q3:`<p>可从花费最大的 ${esc(groups[0].name)} 下钻，找到主要活动，再检查关键词；选择其他渠道也应解释依据。</p><p>主表零预订记录共 ${num(d.audit.zeroBookings)} 条，对应花费 ${usd(aggregate(d.rows.filter(r=>r.bookings===0)).cost,2)}。这是待调查的投入规模，不等于可以无损节省的预算。</p><p>有效行动应说明筛选范围、样本量、具体动作和验证指标。匹配与出价策略的相关性不足以确定其因果效果。</p>`,q4:`<p>精确沿用历史花费、CPC、CVR 和每次预订收入时，基准情景应还原历史销售收入 ${usd(t.revenue,2)}。同预算分配按美分对齐，与精确历史花费的复算可能存在小额差异。</p><p>好的方案应写清预算约束、保守情景、观察窗口、停止规则与复盘指标。未来收益仅是显式假设下的情景，不能称为利润预测。</p><p>若要证明额外订单由广告产生，还需要有效对照实验等识别证据；当前主表不能直接回答。</p>`};return `<section class="panel text-block"><div class="eyebrow">讲师参考 / 非官方标准答案</div><h2>检查数值，也检查推理</h2>${copy[id]}<div class="notice info"><p>数值由当前文件计算；经营建议是独立改编的参考思路，允许存在有证据支持的不同方案。</p></div></section>${note(id)}`}
function lesson(id){const l=lessons.find(x=>x.id===id);const content=state.tab==='task'?task(id):!state.data?empty():(extra.gate(id,state.tab)||(state.tab==='reference'?extra.reference(id)+reference(id):({q1,q2,q3,q4}[id])()));return head(`DECISION ${l.n} / ${l.tag}`,l.title,l.desc,`<span class="pill subtle">${l.time} 分钟 · 25 分</span>`)+`<div class="tabs" role="tablist" aria-label="题目视图">${[['task','题目与交付'],['analysis','分析工作台'],['reference','讲评与参考']].map(([k,v])=>`<button role="tab" id="tab-${k}" aria-controls="lesson-content" aria-selected="${state.tab===k}" tabindex="${state.tab===k?'0':'-1'}" class="${state.tab===k?'selected':''}" data-action="tab" data-tab="${k}">${v}</button>`).join('')}</div>${state.tab!=='task'?source():''}<div id="lesson-content" role="tabpanel" aria-labelledby="tab-${state.tab}">${content}</div><div class="lesson-navigation"><a class="button" href="#${id==='q1'?'brief':'q'+(Number(l.n)-1)}">← ${id==='q1'?'案例简报':'上一道题'}</a><a class="button primary" href="#${id==='q4'?'notes':'q'+(Number(l.n)+1)}">${id==='q4'?'整理我的记录':'下一道题'} →</a></div>`}
function dictionary(){return `<div class="table-scroll"><table><caption>指标口径与公式</caption><thead><tr><th>指标</th><th>计算方式</th><th>单位</th><th>注意事项</th></tr></thead><tbody>${metricDefinitions.map(m=>`<tr><th>${m[0]}<small>${m[1]}</small></th><td>${m[2]}</td><td>${m[3]}</td><td class="prose-cell">${m[4]}</td></tr>`).join('')}</tbody></table></div>`}
function data(){const d=state.data;let detail='';if(d){const size=12;state.tablePage=Math.min(state.tablePage,Math.max(0,Math.ceil(d.rows.length/size)-1));detail=source()+`<section class="panel"><div class="section-head no-margin"><h2>导入检查</h2><button class="button compact" data-action="download-original">下载当前原文件 ↓</button></div><div class="audit-grid">${[['主表记录',num(d.rows.length)],['渠道',num(groupRows(d.rows,'publisher').length)],['活动名称',num(groupRows(d.rows,'campaign').length)],['预订高于点击',num(d.audit.bookingsAboveClicks)],['零预订',num(d.audit.zeroBookings)],['零点击',num(d.audit.zeroClicks)],['重复渠道+关键词键',num(d.audit.duplicateKeywordKeys)],['缺少曝光',num(d.audit.missingImpressions)]].map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="notice"><p>保留 ${d.audit.bookingsAboveClicks} 条预订高于点击的记录。可核对归因和计数口径，仅凭此表不能确认原因。重复键也不自动删除。</p></div><p class="small">跳过 ${d.audit.blankRows} 行空白、${d.audit.summaryRows} 行明确标注的合计。${esc(d.meta.period)}</p><details><summary>查看来源与校验指纹</summary><dl class="source-details"><dt>文件</dt><dd>${esc(d.meta.filename)}</dd><dt>来源状态</dt><dd>${esc(d.meta.authority)}</dd><dt>工作表</dt><dd>${d.meta.sheets.map(esc).join(' / ')}</dd><dt>SHA-256</dt><dd><code>${esc(d.meta.sha256||'当前环境未提供')}</code></dd>${d.meta.sourceUrl?`<dt>镜像</dt><dd><a href="${esc(d.meta.sourceUrl)}" target="_blank" rel="noopener">查看公开课程仓库 ↗</a></dd>`:''}</dl></details></section><section class="panel"><h2>主表预览</h2><div class="table-scroll"><table><caption>原表行号与主要分析字段，每页 12 行</caption><thead><tr><th>源行</th><th>渠道</th><th>活动</th><th>关键词</th><th>点击</th><th>花费</th><th>预订</th><th>收入</th></tr></thead><tbody>${d.rows.slice(state.tablePage*size,(state.tablePage+1)*size).map(r=>`<tr><td>${r.sourceRow}</td><th>${esc(r.publisher)}</th><td>${esc(r.campaign)}</td><td>${esc(r.keyword)}</td><td>${num(r.clicks)}</td><td>${usd(r.cost,2)}</td><td>${num(r.bookings)}</td><td>${usd(r.revenue,2)}</td></tr>`).join('')}</tbody></table></div>${pager(state.tablePage,d.rows.length,size,'preview-page')}</section>${d.kayak?`<section class="panel"><h2>Kayak · 单独核对</h2><p>${esc(d.meta.kayakPeriod)}。期间与粒度独立，不并入主表。</p>${metricsTable([{name:'Kayak（独立期间）',...aggregate([d.kayak])}],{caption:'Kayak 独立汇总'})}</section>`:''}<section class="panel"><h2>当前文件的字段映射</h2><div class="mapping-grid">${Object.entries(d.meta.mappedColumns).map(([k,v])=>`<div><code>${esc(v)}</code><span>→ ${esc(k)}</span></div>`).join('')}</div></section>`}
return head('DATA & DEFINITIONS','把数据准备好，把口径说清楚。','支持原始 XLS / XLSX，以及保留表头的 CSV。文件仅在当前浏览器读取。')+`<section class="panel"><div class="import-grid"><div><h2>${d?'当前案例文件':'导入 Air France 配套表格'}</h2><p>选择 KEL321 工作簿，系统会识别 DoubleClick 明细与 Kayak 汇总。</p><label class="file-button button primary" for="case-file">${d?'更换案例文件':'选择 Excel / CSV 文件'} ↗</label><input id="case-file" type="file" accept=".xls,.xlsx,.csv" class="file-input"><span class="small file-hint">上限 20 MB · 不上传到服务器</span>${localAvailable?'<div class="local-import"><button class="button quiet" data-action="load-local">载入本地课程镜像</button><span class="small">本地已下载的公开课程副本，尚未与官方版本核对。</span></div>':''}<div id="import-message" class="import-message" role="status"></div></div><div class="import-side"><span class="eyebrow">SOURCE MATTERS</span><h3>KEL319 + KEL321</h3><p>正文与数据附件是两份材料。保留来源和原件，缺失数据不会自动补零。</p><a href="${sources.data}" target="_blank" rel="noopener">查看官方数据入口 ↗</a></div></div></section>${detail}<section class="panel"><h2>本课程的指标口径</h2>${dictionary()}</section>`}
function brief(){return head('CASE BRIEF / AIR FRANCE','一份预算，多个渠道。','先理解业务决策，再进入数据。')+`<div class="grid-main"><div><section class="panel text-block"><h2>你要解决什么问题</h2><p>Air France 与 Media Contacts 希望改善搜索广告的销售回报。分析需要比较搜索渠道、广告活动与关键词的表现，提出预算和投放策略调整建议。</p><p>你的角色是经营分析人员：把现有表现转成可解释、可执行、可验证的决策。四道题是围绕正式案例独立改编的教学内容，并非原版题目或标准答案的复制。</p><a href="${sources.case}" target="_blank" rel="noopener">阅读 Kellogg 官方案例背景 ↗</a></section><section class="panel text-block"><h2>上机交付什么</h2><a class="button compact" href="/downloads/course-guide.md" download>下载完整上机题目 ↓</a> <a class="button compact" href="/downloads/teaching-guide.md" download>讲师组织指南 ↓</a><ol>${lessons.map(l=>`<li><strong>${l.title}：</strong>${l.output}。</li>`).join('')}</ol><p>10 分钟导入、20 分钟口径审计、25 分钟分层比较、30 分钟差异诊断、25 分钟预算答辩、10 分钟讲评，共 120 分钟。先独立计算并保存初判，再打开工作台；提交三项证据后进入讲评。每题记录保存在此浏览器，可统一导出。</p></section><section class="panel text-block"><h2>这份案例的范围</h2><p>覆盖搜索广告经营评价、渠道配置、投放诊断和决策复盘。这是历史教学案例，不代表今天广告平台的产品操作。</p><p>主表没有日期序列、逐次竞价、退款、用户路径或随机对照数据。课程不构造这些字段，也不从历史关联直接推断广告因果增量。</p><div class="notice info"><p>Kayak 单独汇总，不自动合并到 DoubleClick；预订量 / 点击不直接等同于用户购买概率。</p></div></section></div><aside class="side-stack"><section class="panel aside-card"><h3>正式教学材料</h3>${pairs([['案例正文','KEL319'],['数据附件','KEL321'],['出版机构','Kellogg']])}<a class="source-link" href="${sources.purchase}" target="_blank" rel="noopener">官方正文入口 ↗</a><a class="source-link" href="${sources.data}" target="_blank" rel="noopener">官方数据入口 ↗</a><p style="margin-top:15px">网站支持导入已取得的表格，不公开打包分发原版教材与数据。</p></section><section class="panel aside-card"><h3>接下来</h3><p>检查数据与口径，再开始第一题。</p><a class="button primary" href="#data">打开数据准备 →</a></section></aside></div>`}
function notes(){return head('MY WORKBOOK','把四个判断，连成一份方案。','作答保存在此浏览器，导出 Markdown 可交给讲师或带到下一次讨论。','<button class="button primary" data-action="export-notes">导出全部作答 ↓</button>')+`<div class="notes-grid">${lessons.map(l=>`<section class="panel"><div class="section-head no-margin"><h2>${l.n} ${l.title}</h2><span class="pill ${extra.submitted(l.id)?'ready':'subtle'}">${extra.submitted(l.id)?'证据已提交':'待完成'}</span></div><p class="small">${l.output}</p><div class="note-preview">${esc(state.notes[l.id]?.text||'还没有分析记录。进入题目后写下你的判断。')}</div>${state.notes[l.id]?.scenario?'<p class="small">含已保存预算情景</p>':''}<a class="button compact" href="#${l.id}">继续本题 →</a></section>`).join('')}</div><div class="notice info"><p>提交表示已填写结论和证据，不代表讲师评阅通过。清理浏览器数据会移除记录，请及时导出。</p></div>`}
return {overview,brief,data,notes,lesson,source,empty};
}
